import sys
import os
import re
import fnmatch
import subprocess

def print_help():
    with open("help.txt", "r") as f:
        print(f.read(), end="")
    sys.exit(0)

def print_help_long():
    with open("help_long.txt", "r") as f:
        print(f.read(), end="")
    sys.exit(0)

def print_version():
    print("fd 10.3.0")
    sys.exit(0)

def error_exit(msg):
    print(f"error: {msg}", file=sys.stderr)
    print("\nUsage: executable [OPTIONS] [pattern] [path]...", file=sys.stderr)
    print("\nFor more information, try '--help'.", file=sys.stderr)
    sys.exit(2)

def parse_args():
    args = sys.argv[1:]

    if "-h" in args:
        print_help()
    if "--help" in args:
        print_help_long()
    if "-V" in args or "--version" in args:
        print_version()

    exec_cmd = None
    exec_batch_cmd = None
    exec_type = None

    opts = {
        'hidden': False,
        'no_ignore': False,
        'case_sensitive': False,
