        arg = args[i]

        if arg in ("-x", "--exec"):
            exec_type = 'x'
            i += 1
            exec_cmd = []
            while i < len(args) and args[i] != ";":
                exec_cmd.append(args[i])
                i += 1
            i += 1 # skip ;
