            exec_type = 'X'
            i += 1
            exec_batch_cmd = []
            while i < len(args) and args[i] != ";":
                exec_batch_cmd.append(args[i])
                i += 1
            i += 1 # skip ;
            continue

        if arg == '--':
            positionals.extend(args[i+1:])
            break

        if arg.startswith('-') and len(arg) > 1:
            if arg in ("-H", "--hidden"): opts['hidden'] = True
            elif arg in ("-I", "--no-ignore"): opts['no_ignore'] = True
            elif arg in ("-u", "--unrestricted"): 
                opts['hidden'] = True
                opts['no_ignore'] = True
            elif arg in ("-s", "--case-sensitive"): opts['case_sensitive'] = True
            elif arg in ("-i", "--ignore-case"): opts['ignore_case'] = True
            elif arg in ("-g", "--glob"): opts['glob'] = True
            elif arg in ("-F", "--fixed-strings"): opts['fixed_strings'] = True
            elif arg in ("-a", "--absolute-path"): opts['absolute_path'] = True
            elif arg in ("-p", "--full-path"): opts['full_path'] = True
            elif arg in ("-L", "--follow"): opts['follow'] = True
            elif arg in ("-0", "--print0"): opts['print0'] = True
            elif arg in ("-q", "--quiet"): opts['quiet'] = True
            elif arg == "--show-errors": opts['show_errors'] = True
            elif arg in ("-t", "--type"):
                i += 1
                if i < len(args): opts['types'].append(args[i])
            elif arg in ("-e", "--extension"):
                i += 1
                if i < len(args): opts['extensions'].append(args[i].lstrip('.'))
            elif arg in ("-E", "--exclude"):
                i += 1
                if i < len(args): opts['excludes'].append(args[i])
            elif arg in ("-d", "--max-depth"):
                i += 1
                if i < len(args): opts['max_depth'] = int(args[i])
            elif arg in ("-c", "--color"):
                i += 1
                if i < len(args): opts['color'] = args[i]
            elif arg in ("-j", "--threads"):
                i += 1
            elif arg == "--search-path":
                i += 1
                if i < len(args): opts['search_paths'].append(args[i])
            elif arg == "--strip-cwd-prefix":
                opts['strip_cwd_prefix'] = True
            elif arg.startswith("--strip-cwd-prefix="):
                opts['strip_cwd_prefix'] = (arg.split("=", 1)[1] == "always")
            else:
                if not arg.startswith('--'):
                    for char in arg[1:]:
                        if char == 'H': opts['hidden'] = True
                        elif char == 'I': opts['no_ignore'] = True
                        elif char == 'u': 
                            opts['hidden'] = True
                            opts['no_ignore'] = True
                        elif char == 's': opts['case_sensitive'] = True
                        elif char == 'i': opts['ignore_case'] = True
                        elif char == 'g': opts['glob'] = True
                        elif char == 'F': opts['fixed_strings'] = True
                        elif char == 'a': opts['absolute_path'] = True
                        elif char == 'p': opts['full_path'] = True
                        elif char == 'L': opts['follow'] = True
                        elif char == '0': opts['print0'] = True
                        elif char == 'q': opts['quiet'] = True
                else:
                    if "=" in arg:
                        k, v = arg.split("=", 1)
                        if k in ("--type", "-t"): opts['types'].append(v)
                        elif k in ("--extension", "-e"): opts['extensions'].append(v.lstrip('.'))
                        elif k in ("--exclude", "-E"): opts['excludes'].append(v)
                        elif k in ("--max-depth", "-d"): opts['max_depth'] = int(v)
                        elif k in ("--color", "-c"): opts['color'] = v
        else:
            positionals.append(arg)

        i += 1

