def match_gitignore(path, rules):
    name = os.path.basename(path)
    for rule in rules:
        if fnmatch.fnmatch(name, rule) or fnmatch.fnmatch(name, rule.rstrip('/')):
            return True
    return False

def get_ignore_rules(dir_path):
    rules = []
    gp = os.path.join(dir_path, '.gitignore')
    if os.path.isfile(gp):
        with open(gp, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    rules.append(line)
    return rules

def walk(dir_path, depth, opts, regex, pattern, rules_stack):
    if opts['max_depth'] is not None and depth > opts['max_depth']:
        return

    try:
        entries = list(os.scandir(dir_path))
    except (PermissionError, OSError) as e:
        if opts['show_errors']:
            print(f"fd error: {e}", file=sys.stderr)
        return

    # sort entries alphabetically for deterministic output
    entries.sort(key=lambda e: e.name)

    current_rules = []
    if not opts['no_ignore']:
        current_rules = get_ignore_rules(dir_path)

    active_rules = rules_stack + [current_rules]
    flattened_rules = [r for sub in active_rules for r in sub]

    for entry in entries:
        if not opts['hidden'] and entry.name.startswith('.'):
            continue

        ignored = False
        if not opts['no_ignore']:
            if match_gitignore(entry.path, flattened_rules):
                ignored = True

        for ex in opts['excludes']:
            if fnmatch.fnmatch(entry.name, ex):
                ignored = True
                break

        if ignored:
            continue

        pass_type = True
        if opts['types']:
            pass_type = False
            for t in opts['types']:
                if t == 'f' and entry.is_file(follow_symlinks=False): pass_type = True
                if t == 'd' and entry.is_dir(follow_symlinks=False): pass_type = True
                if t == 'l' and entry.is_symlink(): pass_type = True

        pass_ext = True
        if opts['extensions']:
            pass_ext = False
            for e in opts['extensions']:
                if entry.name.endswith('.' + e) or entry.name == e:
                    pass_ext = True

        to_match = entry.path if opts['full_path'] else entry.name
        is_match = False
        if not pattern:
            is_match = True
        elif regex.search(to_match):
            is_match = True

        if is_match and pass_type and pass_ext:
            yield entry.path, entry.is_dir(follow_symlinks=False)

        if entry.is_dir(follow_symlinks=opts['follow']):
            yield from walk(entry.path, depth + 1, opts, regex, pattern, active_rules)

def main():
    opts, pos, exec_cmd, exec_batch_cmd, exec_type = parse_args()

    search_paths = opts['search_paths']
    pattern = ""
    implicit_path = False
    explicit_dot = False

    if not search_paths:
        if len(pos) == 0:
            implicit_path = True
            search_paths = ["."]
        elif len(pos) == 1:
            pattern = pos[0]
            implicit_path = True
            search_paths = ["."]
        else:
            pattern = pos[0]
            search_paths = pos[1:]
    else:
