    for sp in search_paths:
        if not os.path.exists(sp):
            print(f"[fd error]: Search path '{sp}' is not a directory.", file=sys.stderr)
            sys.exit(1)
        if not os.path.isdir(sp):
            print(f"[fd error]: Search path '{sp}' is not a directory.", file=sys.stderr)
            sys.exit(1)

