            results.append((path, is_d))

    if opts['quiet']:
        sys.exit(0 if results else 1)

    strip_prefix = implicit_path
    if exec_type or opts['print0']:
        strip_prefix = False
    if opts['strip_cwd_prefix']:
        strip_prefix = True

    final_paths = []
    for path, is_d in results:
        p = path
        if strip_prefix and p.startswith("./"):
            p = p[2:]
        if opts['absolute_path']:
            p = os.path.abspath(p)
        if is_d:
            p += "/"
        final_paths.append(p)

    if exec_type == 'x':
        for p in final_paths:
            cmd = []
            if not exec_cmd:
                cmd = [p]
            else:
                for c in exec_cmd:
                    cmd.append(c.replace('{}', p).replace('{/}', os.path.basename(p.rstrip('/'))))
            subprocess.run(cmd)
    elif exec_type == 'X':
        if final_paths:
            cmd = []
            if not exec_batch_cmd:
                cmd = final_paths
            else:
                has_placeholder = False
                for c in exec_batch_cmd:
                    if '{}' in c:
                        has_placeholder = True
                        # If placeholder, we might need to expand?
                        # fd replaces {} with ALL paths? No, "exec_batch_cmd + final_paths"
                        pass
                if has_placeholder:
                    for c in exec_batch_cmd:
                        if c == '{}':
                            cmd.extend(final_paths)
                        else:
                            cmd.append(c)
                else:
                    cmd = exec_batch_cmd + final_paths
            subprocess.run(cmd)
    else:
        sep = '\0' if opts['print0'] else '\n'
        for p in final_paths:
            sys.stdout.write(p + sep)

